```js

    select: function () {
        // 初始化表格参数配置
        Table.api.init({
            extend: {
                index_url: 'wanlshop/street_coupon/select',
            }
        });
        var urlArr = [];

        var table = $("#table");

        // 多选的 操作
        table.on('check.bs.table uncheck.bs.table check-all.bs.table uncheck-all.bs.table', function (e, row) {
            if (e.type == 'check' || e.type == 'uncheck') {
                row = [row];
            } else {
                urlArr = [];
            }
            $.each(row, function (i, j) {
                if (e.type.indexOf("uncheck") > -1) {
                    var index = urlArr.indexOf(j.id);
                    if (index > -1) {
                        urlArr.splice(index, 1);
                    }
                } else {
                    urlArr.indexOf(j.id) == -1 && urlArr.push(j.id);
                }
            });
        });

        // 初始化表格
        table.bootstrapTable({
            url: $.fn.bootstrapTable.defaults.extend.index_url,
            sortName: 'id',
            showToggle: false,
            showExport: false,

            //是否显示右上角的搜索框
            search: false,
            //控制显示列开关
            showColumns:false,
            //显示搜索字段框
            searchFormVisible: false,
            showExport: false,
            columns: [
                [
                    {
                        field: 'type',
                        title: __('Type'),
                        searchList: {
                            "reduction": "满减券",
                            "discount": "折扣券",
                            "daijin": "代金券",
                            "stopcar": "停车券",
                            "gift": "礼品券"
                        },
                        formatter: Table.api.formatter.normal
                    },
                    {field: 'name', title: __('Name'), operate: 'LIKE'},
                    {field: 'drawlimit', title: __('Drawlimit')},
                    {field: 'grant', title: __('Grant'), operate: 'LIKE',formatter: Controller.api.formatter.grant},
                    {
                        field: 'operate', title: __('Operate'), events: {
                            'click .btn-chooseone': function (e, value, row, index) {
                                // var multiple = Backend.api.query('multiple');
                                // multiple = multiple == 'true' ? true : false;
                                Fast.api.close({
                                    id: row.id,
                                    name: row.name,
                                    type: row.type_text,
                                    drawlimit: row.drawlimit,
                                    grant: row.grant
                                });
                            },
                        }, formatter: function () {
                            return '<a href="javascript:;" class="btn btn-danger btn-chooseone btn-xs"><i class="fa fa-check"></i> ' + __('Choose') + '</a>';
                        }
                    }
                ]
            ],
            queryParams: function(params){
                var filter = JSON.parse(params.filter);
                var op = JSON.parse(params.op);
                var select_use_type = Fast.api.query('select_use_type');

                if (select_use_type != null){
                    filter.use_type= select_use_type;
                    op.use_type = "=";
                }
                params.filter = JSON.stringify(filter);
                params.op = JSON.stringify(op);
                return params;
            }
        });
        // 为表格绑定事件
        Table.api.bindevent(table);
    },
```

